public class Solution {
    // SPEC: largest sum of any k consecutive elements
    public static int maxWindowSum(int[] arr, int k) {
        int best = Integer.MIN_VALUE;
        for (int i = 0; i + k < arr.length; i++) {
            int sum = 0;
            for (int j = i; j < i + k; j++) {
                sum += arr[j];
            }
            if (sum > best) {
                best = sum;
            }
        }
        return best;
    }
}
